(function(){'use strict';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],T=()=>NotaThinking;
function calculator(n,c){const calc=n.calculator;NotaModeEditors.shell(n,c,'Calculator',`<p class="mode-lead">A number now. A thought to keep.</p><div class="calc-display"><label for="calc-expression">Calculation</label><input id="calc-expression" maxlength="180" inputmode="decimal" value="${c.esc(calc.expression)}" placeholder="(24 + 8) / 4" autocomplete="off"><output id="calc-answer" aria-live="polite"></output></div><div class="calc-keypad" aria-label="Calculator keypad">${[['clear','C'],['back','⌫'],['(','('],[')',')'],['7','7'],['8','8'],['9','9'],['/','÷'],['4','4'],['5','5'],['6','6'],['*','×'],['1','1'],['2','2'],['3','3'],['-','−'],['0','0'],['.','.'],['%','%'],['+','+'],['^','xʸ'],['sign','±'],['equals','=']].map(([v,label])=>`<button data-calc-key="${v}" ${v==='equals'?'class="primary calc-equals"':''} aria-label="${v==='back'?'Delete last character':v==='clear'?'Clear calculation':v==='equals'?'Calculate':v==='sign'?'Change sign':c.esc(label)}">${label}</button>`).join('')}</div><button id="calc-keep" class="secondary" disabled><i data-lucide="file-check"></i> Keep this calculation</button><section class="calc-box-section"><label for="calc-box">Math box</label><p class="hint">Write an equation on its own line and finish with =. Keep words and calculations together.</p><div id="calc-box" contenteditable="true" role="textbox" aria-multiline="true" class="editor calc-box">${c.esc(calc.box).replace(/\n/g,'<br>')}</div></section><details class="calc-history"><summary>Recent calculations</summary><div id="calc-history"></div></details>`);
 let current=null;const persist=NotaModeEditors.common(n,c,()=>T().calculatorHTML(calc),()=>detach());const expression=$('#calc-expression'),box=$('#calc-box');const sync=()=>{calc.expression=expression.value.slice(0,180);calc.box=box.innerText.slice(0,20000);persist();};const history=()=>{$('#calc-history').innerHTML=calc.history.length?calc.history.map((h,i)=>`<button data-calc-history="${i}"><span>${c.esc(h.expression)}</span><strong>= ${c.esc(h.result)}</strong></button>`).join(''):'<p class="hint">Calculate something to keep a short history here.</p>';$$('[data-calc-history]').forEach(el=>el.onclick=()=>{const h=calc.history[Number(el.dataset.calcHistory)];expression.value=h.expression;current=h;$('#calc-answer').textContent=String(h.result);$('#calc-keep').disabled=false;sync();});};
 const solve=()=>{sync();try{T().calculate(calc,c.calculate);current=calc.history[0];$('#calc-answer').textContent=String(current.result);$('#calc-keep').disabled=false;history();persist();}catch(error){current=null;$('#calc-answer').textContent=error.message;$('#calc-keep').disabled=true;}};
 expression.oninput=()=>{current=null;$('#calc-answer').textContent='';$('#calc-keep').disabled=true;sync();};expression.onkeydown=e=>{if(e.key==='Enter'||e.key==='='){e.preventDefault();solve();}};box.addEventListener('input',sync);box.addEventListener('paste',e=>{e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain').slice(0,20000));sync();});const detach=NotaMath.attach(box,{enabled:()=>true,onChange:sync});
 $$('[data-calc-key]').forEach(button=>button.onclick=()=>{const key=button.dataset.calcKey;if(key==='equals'){solve();return;}if(key==='clear')expression.value='';else if(key==='back')expression.value=expression.value.slice(0,-1);else if(key==='sign')expression.value=expression.value.startsWith('-(')&&expression.value.endsWith(')')?expression.value.slice(2,-1):expression.value?'-('+expression.value+')':'-';else if(expression.value.length<180)expression.value+=key;expression.oninput();});$('#calc-keep').onclick=()=>{if(!current)return;sync();c.promote({title:current.expression+' = '+current.result,text:current.expression+' = '+current.result,task:false,parent:n,onId:()=>{}});};history();c.icons();
}
function choice(n,c){const model=n.choice;NotaModeEditors.shell(n,c,'Choice Weaver',`<p class="mode-lead">Weigh choices. Find clarity.</p><p class="hint">Start with what each option gives you and asks of you. Add weights when a structured comparison helps.</p><div class="mode-tabs" role="tablist" aria-label="Comparison view"><button role="tab" data-choice-view="simple">Pros & cons</button><button role="tab" data-choice-view="weighted">Weighted view</button></div><div id="choice-options"></div><button id="choice-add-option" class="secondary"><i data-lucide="plus"></i> Add an option</button><section id="choice-weighted"><p class="hint">Rate each option from 1 to 5. Mark whether higher or lower is preferable. Weights run from 0 to 10; zero leaves a criterion out.</p><div id="choice-criteria"></div><button id="choice-add-criterion" class="secondary"><i data-lucide="plus"></i> Add a criterion</button><div id="choice-grid" class="thinking-table-scroll"></div><div id="choice-results" aria-live="polite"></div></section>`);
 const persist=NotaModeEditors.common(n,c,()=>T().choiceHTML(model));
 const results=()=>{const r=T().choiceResults(model);$('#choice-results').innerHTML=r.error?`<p class="planner-error">${c.esc(r.error)}</p>`:!r.complete?'<p class="hint">Finish every rating with a positive weight before comparing scores.</p>':`<h3>Based on your priorities</h3><p class="hint">${r.winners.length>1?'Your current ratings produce a tie.':'The highest score reflects the values you entered.'} Scores help a discussion; you choose what matters.</p>${[...r.rows].sort((a,b)=>b.score-a.score).map(row=>`<section class="choice-result"><strong>${c.esc(row.label||'Untitled option')}</strong><span>${row.score} / 100</span><details><summary>Show the working</summary>${row.working.map(w=>`<p>${c.esc(w.label)}: ${w.ignored?'not counted':`${w.rating}/5, ${w.prefer} preferred · weight ${w.weight} → ${w.contribution.toFixed(2)} points`}</p>`).join('')}</details></section>`).join('')}`;persist();};
 const grid=()=>{$('#choice-grid').innerHTML=`<table><caption>Option ratings · 1 to 5</caption><thead><tr><th>Option</th>${model.criteria.map(r=>`<th>${c.esc(r.label||'Criterion')}</th>`).join('')}</tr></thead><tbody>${model.options.map(o=>`<tr><th>${c.esc(o.label||'Option')}</th>${model.criteria.map(r=>`<td><input type="number" min="1" max="5" step="1" inputmode="numeric" data-choice-score="${o.id}" data-criterion="${r.id}" aria-label="${c.esc(o.label||'Option')} · ${c.esc(r.label||'Criterion')} rating" value="${c.esc(model.scores[o.id]?.[r.id]||'')}"></td>`).join('')}</tr>`).join('')}</tbody></table>`;$$('[data-choice-score]').forEach(input=>input.oninput=()=>{model.scores[input.dataset.choiceScore]??={};model.scores[input.dataset.choiceScore][input.dataset.criterion]=input.value.slice(0,2);const valid=/^[1-5]$/.test(input.value);input.setAttribute('aria-invalid',String(input.value!==''&&!valid));results();});};
 const render=()=>{$$('[data-choice-view]').forEach(button=>button.setAttribute('aria-selected',String(button.dataset.choiceView===model.view)));$('#choice-weighted').hidden=model.view!=='weighted';$('#choice-options').innerHTML=model.options.map(o=>`<section class="thinking-panel"><header><label>Option<input data-option-field="label" data-option-id="${o.id}" maxlength="100" placeholder="Name this option…" value="${c.esc(o.label)}"></label><button data-choice-remove-option="${o.id}" class="icon-button" aria-label="Remove ${c.esc(o.label)}" ${model.options.length<=2?'disabled':''}><i data-lucide="trash-2"></i></button></header><div class="choice-pros-cons"><label>What it gives me<textarea data-option-field="pros" data-option-id="${o.id}" rows="4" maxlength="4000">${c.esc(o.pros)}</textarea></label><label>What it asks of me<textarea data-option-field="cons" data-option-id="${o.id}" rows="4" maxlength="4000">${c.esc(o.cons)}</textarea></label></div></section>`).join('');$('#choice-criteria').innerHTML=model.criteria.map(r=>`<section class="choice-criterion"><label>Criterion<input data-criterion-field="label" data-criterion-id="${r.id}" maxlength="100" placeholder="Effort, cost, impact…" value="${c.esc(r.label)}"></label><label>Weight<input data-criterion-field="weight" data-criterion-id="${r.id}" inputmode="numeric" maxlength="2" value="${c.esc(r.weight)}"></label><label>Prefer<select data-criterion-field="prefer" data-criterion-id="${r.id}"><option value="higher" ${r.prefer==='higher'?'selected':''}>Higher</option><option value="lower" ${r.prefer==='lower'?'selected':''}>Lower</option></select></label><button class="icon-button" data-choice-remove-criterion="${r.id}" aria-label="Remove ${c.esc(r.label)}" ${model.criteria.length===1?'disabled':''}><i data-lucide="trash-2"></i></button></section>`).join('');
 $$('[data-option-field]').forEach(el=>el.oninput=()=>{model.options.find(o=>o.id===el.dataset.optionId)[el.dataset.optionField]=el.value;if(el.dataset.optionField==='label')grid();results();});$$('[data-criterion-field]').forEach(el=>{const update=()=>{model.criteria.find(r=>r.id===el.dataset.criterionId)[el.dataset.criterionField]=el.value;if(el.dataset.criterionField==='label')grid();results();};if(el.tagName==='SELECT')el.onchange=update;else el.oninput=update;});
 $$('[data-choice-remove-option]').forEach(button=>button.onclick=()=>{if(model.options.length<=2||!confirm('Remove this option, its notes, and its ratings?'))return;model.options=model.options.filter(o=>o.id!==button.dataset.choiceRemoveOption);delete model.scores[button.dataset.choiceRemoveOption];render();});$$('[data-choice-remove-criterion]').forEach(button=>button.onclick=()=>{if(model.criteria.length===1||!confirm('Remove this criterion and its ratings?'))return;const id=button.dataset.choiceRemoveCriterion;model.criteria=model.criteria.filter(r=>r.id!==id);for(const scores of Object.values(model.scores))delete scores[id];render();});$('#choice-add-option').disabled=model.options.length>=8;$('#choice-add-criterion').disabled=model.criteria.length>=8;grid();results();c.icons();};
 $$('[data-choice-view]').forEach(button=>button.onclick=()=>{model.view=button.dataset.choiceView;render();});$('#choice-add-option').onclick=()=>{if(model.options.length>=8)return;model.options.push({id:c.uid(),label:'',pros:'',cons:''});render();};$('#choice-add-criterion').onclick=()=>{if(model.criteria.length>=8)return;model.criteria.push({id:c.uid(),label:'',weight:'1',prefer:'higher'});render();};render();
}
function reference(n,c){const lab=n.reference;let query='';NotaModeEditors.shell(n,c,'Reference Lab',`<p class="mode-lead">Your personal cheat sheet.</p><p class="hint">Keep the answer, an example, and a source within reach. Add your own fields and connect related entries.</p><label class="field">Find a reference<input id="reference-search" type="search" placeholder="Search titles, tags, or details"></label><div class="planner-actions"><button id="reference-add" class="secondary"><i data-lucide="plus"></i> Add a reference</button><button id="reference-view" class="secondary">Table view</button><button id="reference-fields" class="secondary">Customize fields</button></div><section id="reference-field-editor" hidden><div id="reference-field-list"></div><label>Field name<input id="reference-new-field" maxlength="60" placeholder="Role, rule, language, source…"></label><button id="reference-add-field" class="secondary">Add field</button></section><div id="reference-browser"></div><div id="reference-editor"></div>`);
 const persist=NotaModeEditors.common(n,c,()=>T().referenceHTML(lab));const matches=()=>lab.cards.filter(card=>[card.title,card.tags,card.body,...Object.values(card.values)].join(' ').toLowerCase().includes(query));
 const browser=()=>{const cards=matches();$('#reference-view').textContent=lab.view==='cards'?'Table view':'Card view';$('#reference-browser').innerHTML=lab.view==='table'?`<div class="thinking-table-scroll"><table><caption>Reference table</caption><thead><tr><th>Reference</th>${lab.fields.map(f=>`<th>${c.esc(f.label)}</th>`).join('')}</tr></thead><tbody>${cards.map(card=>`<tr><th><button data-reference-open="${card.id}">${c.esc(card.title||'Untitled reference')}</button></th>${lab.fields.map(f=>`<td>${c.esc(card.values[f.id]||'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<div class="reference-list">${cards.map(card=>`<button data-reference-open="${card.id}" aria-pressed="${card.id===lab.selected}"><strong>${c.esc(card.title||'Untitled reference')}</strong><small>${c.esc(card.tags||lab.fields.map(f=>card.values[f.id]).filter(Boolean).join(' · ').slice(0,140))}</small></button>`).join('')}</div>`;if(!cards.length)$('#reference-browser').innerHTML='<p class="hint">No matching references. Try a different word.</p>';$$('[data-reference-open]').forEach(button=>button.onclick=()=>{lab.selected=button.dataset.referenceOpen;render();});};
 const fields=()=>{$('#reference-field-list').innerHTML=lab.fields.map(f=>`<div class="reference-field-row"><label>Field<input data-reference-field-label="${f.id}" maxlength="60" value="${c.esc(f.label)}"></label><button data-reference-remove-field="${f.id}" class="icon-button" aria-label="Remove ${c.esc(f.label)} field"><i data-lucide="trash-2"></i></button></div>`).join('');$$('[data-reference-field-label]').forEach(input=>input.oninput=()=>{lab.fields.find(f=>f.id===input.dataset.referenceFieldLabel).label=input.value;persist();browser();});$$('[data-reference-remove-field]').forEach(button=>button.onclick=()=>{const id=button.dataset.referenceRemoveField;if(!confirm('Remove this field and its values from every reference?'))return;lab.fields=lab.fields.filter(f=>f.id!==id);for(const card of lab.cards)delete card.values[id];render();});$('#reference-add-field').disabled=lab.fields.length>=8;c.icons();};
 const render=()=>{browser();fields();$('#reference-add').disabled=lab.cards.length>=120;const card=lab.cards.find(card=>card.id===lab.selected);if(!card){$('#reference-editor').innerHTML='<p class="hint">Add a reference to begin.</p>';persist();return;}$('#reference-editor').innerHTML=`<section class="thinking-panel"><header><h3>Reference details</h3><button id="reference-remove" class="icon-button" aria-label="Delete this reference"><i data-lucide="trash-2"></i></button></header><label>Title<input id="reference-title" maxlength="160" value="${c.esc(card.title)}"></label><label>Tags<input id="reference-tags" maxlength="300" value="${c.esc(card.tags)}" placeholder="Separate topics with commas"></label>${lab.fields.map(f=>`<label>${c.esc(f.label||'Field')}<textarea data-reference-value="${f.id}" rows="3" maxlength="2000">${c.esc(card.values[f.id]||'')}</textarea></label>`).join('')}<label>More detail<textarea id="reference-body" rows="5" maxlength="6000">${c.esc(card.body)}</textarea></label><section class="reference-links"><h4>Related references</h4>${card.links.map(id=>`<button data-reference-related="${id}">${c.esc(lab.cards.find(c=>c.id===id)?.title||'Reference')} <span aria-hidden="true">↗</span></button><button data-reference-unlink="${id}" aria-label="Remove reference link">×</button>`).join('')}<label>Link another entry<select id="reference-link"><option value="">Choose a reference…</option>${lab.cards.filter(o=>o!==card&&!card.links.includes(o.id)).map(o=>`<option value="${o.id}">${c.esc(o.title||'Untitled reference')}</option>`).join('')}</select></label></section><button id="reference-note" class="secondary"><i data-lucide="file-text"></i> ${card.noteId?'Open linked note':'Keep as a note'}</button></section>`;
 const update=()=>{card.title=$('#reference-title').value;card.tags=$('#reference-tags').value;card.body=$('#reference-body').value;for(const input of $$('[data-reference-value]'))card.values[input.dataset.referenceValue]=input.value;persist();browser();};for(const input of $$('[data-reference-value],#reference-title,#reference-tags,#reference-body'))input.oninput=update;$('#reference-link').disabled=card.links.length>=8;$('#reference-link').onchange=e=>{if(e.target.value&&card.links.length<8)card.links.push(e.target.value);render();};$$('[data-reference-related]').forEach(button=>button.onclick=()=>{lab.selected=button.dataset.referenceRelated;render();});$$('[data-reference-unlink]').forEach(button=>button.onclick=()=>{card.links=card.links.filter(id=>id!==button.dataset.referenceUnlink);render();});$('#reference-remove').onclick=()=>{if(!confirm('Delete this reference? Linked notes are kept.'))return;T().removeReferenceCard(lab,card.id);render();};$('#reference-note').onclick=()=>{update();c.promote({id:card.noteId,title:card.title||'A reference to keep',text:lab.fields.map(f=>f.label+': '+(card.values[f.id]||'')).join('\n')+(card.body?'\n\n'+card.body:''),task:false,parent:n,onId:id=>card.noteId=id});};persist();c.icons();};
 $('#reference-search').oninput=()=>{query=$('#reference-search').value.toLowerCase().trim();browser();};$('#reference-add').onclick=()=>{if(lab.cards.length>=120)return;const card={id:c.uid(),title:'',tags:'',body:'',values:{},links:[]};lab.cards.push(card);lab.selected=card.id;query='';$('#reference-search').value='';render();$('#reference-title').focus();};$('#reference-view').onclick=()=>{lab.view=lab.view==='cards'?'table':'cards';browser();persist();};$('#reference-fields').onclick=()=>$('#reference-field-editor').hidden=!$('#reference-field-editor').hidden;$('#reference-add-field').onclick=()=>{const label=$('#reference-new-field').value.trim();if(!label||lab.fields.length>=8)return;lab.fields.push({id:c.uid(),label});$('#reference-new-field').value='';render();};render();
}
window.NotaThinkingEditors={calculator,choice,reference};
})();
